const JSONProducts = {};
class getJSONProduct {
  static load(productHandle, variantsPages = 1) {
    if (!productHandle) {
      return;
    }
    if (JSONProducts[productHandle]) {
      return JSONProducts[productHandle];
    }

    JSONProducts[productHandle] = new Promise(async (resolve, reject) => {
      try {
        const url = `${Shopify.routes.root}products/${productHandle}?section_id=product-variants`;

        const response = await fetch(url);
        if (!response.ok) {
          reject(`${productHandle} not loaded section variants`);
          return;
        }

        const htmlText = await response.text();
        const parser = new DOMParser();
        const doc = parser.parseFromString(htmlText, 'text/html');
        const scriptEl = doc.getElementById('hdt-product-variants-json');

        let product;
        if (scriptEl && scriptEl.textContent) {
          product = JSON.parse(scriptEl.textContent);
        } else {
          const match = htmlText.match(/<script[^>]*id=["']hdt-product-variants-json["'][^>]*>([\s\S]*?)<\/script>/i);
          if (match && match[1]) {
            product = JSON.parse(match[1]);
          } else {
            product = JSON.parse(htmlText);
          }
        }

        resolve(product);
      } catch (error) {
        delete JSONProducts[productHandle];
        reject(error);
      }
    });

    return JSONProducts[productHandle];
  }
};

const optionsProducts = {};
class getOptionsProduct {
  static async load(productHandle, valueId = [], sectionId = '') {
    if (!productHandle) {
      return;
    }
    const vIds = valueId.join('')
    if (optionsProducts[vIds + sectionId]) {
      return optionsProducts[vIds + sectionId];
    }
    
    optionsProducts[vIds + sectionId] = (async () => {
      try {
        const response = await fetch(`${Shopify.routes.root}products/${productHandle}?option_values=${valueId.join(',')}&section_id=${sectionId}`);
        if (response.ok) {
          const responseAs = await response.text();
          return responseAs;
        } else {
          throw new Error(`${productHandle} not loaded json`);
        }
      } catch (error) {
        delete optionsProducts[vIds + sectionId];
        throw error;
      }
    })();
    
    return optionsProducts[vIds + sectionId];
  }
};

// Visibilitychange
function visibilitychangeFn(options) {
  if (!options.observes) return;
  const checkVisibility = () => {
    if (document.visibilityState === 'visible') {
      if (isFunction(options.play) && options.observes.isInview) options.play();
    } else if (isFunction(options.pause)) {
      options.pause();
    }
  }
  document.addEventListener('visibilitychange', checkVisibility);

}

/**
 * Wrap tables in a container div to make them scrollable when needed
 */
function rteWrapTable(doc = document) {
  const tables = $$4('.hdt-rte table:not(.hdt-wrapper-added)', doc);
  if (tables.length == 0) return
  tables.forEach((table) => {
    table.classList.add('hdt-wrapper-added');
    table.outerHTML = `<div class="hdt-scrollable-wrapper">${table.outerHTML}</div>`;
  });
}

/**
 * Add aria-describedby attribute to external and new window links
 */
function accessibleLinks(doc = document) {
  const { hostname } = window.location,
  links = $$4('a[href]:not([aria-describedby])', doc);
  if (links.length == 0) return;

  links.forEach((link) => {
    const isExternal  = link.hostname !== hostname,
        isTargetBlank = link.getAttribute('target') === '_blank';

    if (isTargetBlank) {
      link.setAttribute('aria-describedby', isExternal ? 'a11y-new-window-external-message' : 'a11y-new-window-message');
      const rel = link.getAttribute('rel');
      if (!rel || rel.indexOf('noopener') === -1) {
        link.setAttribute('rel',`${rel ? rel + ' '  : ''}noopener`);
      }
    } else if (isExternal) {
      link.setAttribute('aria-describedby', 'a11y-external-message');
    }
  });
}

/** Link Mylti Lang **/
function localeUrl(doc = document) {
  const {root} = Shopify.routes,
        {hostname} = window.location;
  if ( root == '/' ) return;
  $$4('a[href="/"]', doc).forEach((el) => el.setAttribute('href', root ));
  $$4(`a[href*="${hostname}/"]:not([href*="${hostname + root}"],[href*="@"],[href*="preview_theme_id="])`, doc).forEach((el) => el.setAttribute('href', el.getAttribute('href').replace( `${hostname}/`, hostname + root ) ));
};

