customElements.define("hdt-append-body", appendToBody);

// reload, update cart drawer
const  {cartUpdate, cartReload, cartCount, cartError, currencyUpdate, cartDrawerRender, cartMainRender} = ThemeEvents;
class CartDrawer extends DrawerComponent {
  #abortController;
  #requiredRefs = ['shipping-bar'];
  //#requiredRefs = ['shipping-bar', 'cart-items', 'cart-bottom', 'complementary', 'contents'];
  constructor() {
    super();
  }
  connectedCallback() {
    super.connectedCallback();
    this.#abortController = new AbortController();
    const {signal} = this.#abortController;
    document.addEventListener(cartUpdate, this.#handleCartUpdate.bind(this), { signal });
    document.addEventListener(cartReload, this.#handleCartReload.bind(this), { signal });
    window.addEventListener("pageshow", this.#handleCartPageShow.bind(this), { signal });
    //this.#handleCartReload();
  }
  disconnectedCallback() {
    super.disconnectedCallback();
    this.#abortController.abort();
  }
  get sectionId() {
    return this._sectionId ??= this.getAttribute('section-id');
  }
  // get sectionsToRender() {
  //   return [
  //     {
  //       id: this.sectionId
  //     }
  //   ];
  // }
  async #handleCartUpdate(event) {
    //console.log('Cart updated:', event.detail);
    const { cartData, source, actionAfterATC } = event.detail,
    newSectionHTML = new DOMParser().parseFromString(cartData.sections[this.sectionId], "text/html");
    //console.log('Cart item updated:', newSectionHTML);
    // Grab the new cart item count from a hidden element
    const newCartHiddenItemCount = $4('[ref="hdt-cart"]', newSectionHTML)?.dataset.count;
    const item_count = newCartHiddenItemCount ? parseInt(newCartHiddenItemCount, 10) : 0;
    const total_price = $4('[ref="hdt-cart"]', newSectionHTML)?.dataset.totalPrice;
    //cartData.item_count = item_count;
    //console.log(cartData);
    document.dispatchEvent(new CartCountEvent(item_count, total_price));
    let animation;
    if (item_count == 0) {
      animation = timeline([
        [$4('.hdt-mini-cart__main', this), { opacity: [1, 0] }, { duration: 0.15, easing: "ease-in" }],
        [$4('.hdt-mini-cart__bottom', this), { opacity: [1, 0], transform: ["translateY(0)", "translateY(30px)"] }, { duration: 0.15, at: "<", easing: "ease-in" }]
      ]);
    } else {
      animation = animate(this, {}, { duration: 0 })
    }
    await animation.finished;
    this.classList.toggle('is-empty', item_count == 0);
    // update gift wrap
    //$4('[aria-controls="dialog-is--gift"]', this)?.parentElement?.toggleAttribute('hidden', $4('.is-gift-wrap', newSectionHTML));
    // Update html
    for (const ref of this.#requiredRefs) {
      const targetElement = $4(`[ref="${ref}"]`, this);
      const sourceElement = $4(`[ref="${ref}"]`, newSectionHTML);
      if (!targetElement || !sourceElement) continue;
      if (ref == this.#requiredRefs[0]) {
        $4('.hdt-progress-bar', sourceElement).style.setProperty('--progress-rate', $4('.hdt-progress-bar', targetElement).style.getPropertyValue('--progress-rate'));
        targetElement.replaceWith(sourceElement);
        $4('.hdt-progress-bar', this).now = $4('.hdt-progress-bar', sourceElement).getAttribute('aria-valuenow');
      } else if (ref != this.#requiredRefs[3]) {
        targetElement.replaceWith(sourceElement);
      } else if ( !sourceElement.dataset.id || targetElement.dataset.id !== sourceElement.dataset.id ) {
        targetElement.replaceWith(sourceElement);
      }
    }
    $4('cart-items-component', this).innerHTML =  $4('cart-items-component', newSectionHTML).innerHTML;
    // End Update html
    if (item_count == 0) {
      animate($4('.hdt-mini-cart__main', this), { opacity: [0, 1], transform: ["translateY(30px)", "translateY(0)"] }, { duration: 0.25, easing: [0.25, 0.46, 0.45, 0.94] });
    }
    document.dispatchEvent(new CustomEvent(currencyUpdate));
    document.dispatchEvent(new CustomEvent(cartDrawerRender));
    if (source === "product-form-component") {
      const _actionAfterATC = actionAfterATC || themeHDN.settings.actionAfterATC;
      if (_actionAfterATC.indexOf('go_') > -1) {
        window.location.href = `${Shopify.routes.root}${_actionAfterATC == 'go_cart_page' ? 'cart' : 'checkout'}`;
      } else if ( _actionAfterATC == 'open_cart_drawer' ) {
        this.open();
      }
    }
  }
  async #handleCartReload() {
    try {
      const config = fetchConfig('json', {
        body: JSON.stringify({ sections: [this.sectionId] }),
      });
      const response = await fetch(`${Shopify.routes.root}cart/update`, {...config});
      if (!response.ok) {
        throw new Error('Network response was not ok');
      }
      const cartData = await response.json();
      //console.log('Cart reloaded:', cartData.item_count);
      this.#handleCartUpdate.call(this, {
        detail: {
          cartData,
          source: 'reload',
          actionAfterATC: 'no_action'
        }
      });
    } catch (error) {
      console.error('Failed to reload cart:', error);
    }
  }
  async #handleCartPageShow(event) {
    if (event.persisted) this.#handleCartReload();
  }
}
class CartAction extends DialogComponent {
  animateDialogOpen() {
    return animate(this.dialog, {
      transform: ['translate3d(0, 100%, 0)', 'translate3d(0, 0, 0)']
    }, {
      duration: 0.5,
      easing: [0.19, 1, 0.22, 1]
    });
  }
  animateDialogClose() {
    return animate(this.dialog, {
      transform: ['translate3d(0, 0, 0)', 'translate3d(0, 100%, 0)']
    }, {
      duration: 0.4,
      easing: [0.19, 1, 0.22, 1]
    });
  }
}
class CartItemsComponent extends HTMLElement {
  #abortController;
  constructor() {
    super();
  }
  connectedCallback() {
    this.#abortController = new AbortController();
    document.addEventListener(ThemeEvents.quantitySelectorUpdate, this.#onQuantityChange.bind(this), { signal: this.#abortController.signal });
  }
  disconnectedCallback() {
    this.#abortController.abort();
  }
  /**
   * Handles QuantitySelectorUpdateEvent change event.
   * @param {QuantitySelectorUpdateEvent} event - The event.
   */
  #onQuantityChange(event) {
    //console.log('Quantity changed:', event.detail);
    const { quantity, line } = event.detail;

    if (!line) return;

    if (quantity === 0) {
      return this.onLineItemRemove(line);
    }
    this.updateQuantity({
      line,
      quantity,
      action: 'change',
    });
    // const lineItemRow = this.cartItemRows[line - 1];

    // if (!lineItemRow) return;
    // Add effect loading
  }

  /**
   * Handles the line item removal.
   * @param {number} line - The line item index.
   */
  onLineItemRemove(line) {
    this.updateQuantity({
      line,
      quantity: 0,
      action: 'clear'
    });
  }

  /**
   * Updates the quantity.
   * @param {Object} config - The config.
   * @param {number} config.line - The line.
   * @param {number} config.quantity - The quantity.
   * @param {string} config.action - The action.
   */
  updateQuantity(config) {

    this.#disableCartItems();

    const { line, quantity, action } = config;

    const body = JSON.stringify({
      line: line,
      quantity: quantity,
      sections: this.cart.sectionId,
      sections_url: window.location.pathname,
    });

    //cartTotal?.shimmer();

    fetch(`${Shopify.routes.root}cart/change.js`, fetchConfig('json', { body }))
      .then((response) => {
        return response.text();
      })
      .then(async (responseText) => {
        const parsedResponseText = JSON.parse(responseText);

        if (parsedResponseText.errors) {
          this.#handleCartError(line, parsedResponseText);
          return;
        }

        // const newSectionHTML = new DOMParser().parseFromString(parsedResponseText.sections[this.cart.sectionId],'text/html');
        // console.log('Cart item updated:', newSectionHTML);
        // // Grab the new cart item count from a hidden element
        // const newCartHiddenItemCount = $4('[ref="hdt-cart"]', newSectionHTML)?.dataset.count;
        // const newCartItemCount = newCartHiddenItemCount ? parseInt(newCartHiddenItemCount, 10) : 0;
        // parsedResponseText.item_count = newCartItemCount;
        // console.log(parsedResponseText)
        let animation = animate(this, {}, { duration: 0 });
        if (action === 'clear') {
          const itemRemove = this.cartItemRows[line - 1];
          if (itemRemove) {
            itemRemove.style.overflow = 'hidden';
            animation = animate(itemRemove, { opacity: [1, 0], height: [`${itemRemove.clientHeight}px`, '0px'], paddingBottom: 0, paddingTop: 0, marginBottom: 0, marginTop: 0, borderColor: 'transparent' }, { duration: 0.25, easing: "ease-in-out" });
          }
        }
        await animation.finished;
        this.dispatchEvent(
          new CartUpdateEvent({}, this.cart.sectionId, parsedResponseText, 'no_action', 'cart-items-component')
        );
      })
      .catch((error) => {
        console.error(error);
      })
      .finally(() => {
        this.#enableCartItems();
      });
  }

  /**
   * Disables the cart items.
   */
  #disableCartItems() {
    this.classList.add('cart-items-disabled');
  }

  /**
   * Enables the cart items.
   */
  #enableCartItems() {
    this.classList.remove('cart-items-disabled');
  }
  #handleCartError = (line, parsedResponseText) => {
    const errorMessage = parsedResponseText.errors.map(error => error.message).join(', ');
    console.error(`Error updating cart item at line ${line}: ${errorMessage}`);
  }
  get cart() {
    return this._cart = this._cart || $4('[ref="hdt-cart"]');
  }
  get cartItemRows() {
    return $$4('[ref="cartItemRows[]"]', this);
  }
}
