    //this.#endingDate = new Date(Date.parse(arrayMth[this.#timerOptions.month] + ' ' + this.#timerOptions.date + this.timezoneString));
    //this.#endingDate = new Date(Date.parse(arrayMth[this.#timerOptions.month] + ' ' + this.#timerOptions.date + (themeHDN.settings.shopTimezone ? ` GMT${themeHDN.settings.shopTimezone}` : "")));
