import { CartAddEvent, CartErrorEvent } from '@theme/events';
class ProductForm extends HTMLElement {
  #abortController;
  /** @type {number | undefined} */
  #timeout;
  constructor() {
    super();
    this.form = $4('form', this);
  }
  connectedCallback() {
    if (!this.form) this.form = $4('form', this);
    this.#abortController = new AbortController();
    const { signal } = this.#abortController;
    if (!this.form) throw new Error('Product form element missing');
    this.form?.addEventListener("submit", this.#handleSubmit.bind(this), { signal });
  }

  disconnectedCallback() {
    this.#abortController.abort();
  }

  /**
   * Handles the submit event for the product form.
   *
   * @param {Event} event - The submit event.
   */
  #handleSubmit(event) {
    const addToCartError = $4('[ref="addToCartTextError"]', this),
    addToCartButton = $4('[type="submit"][name="add"]', this);
    // Stop default behaviour from the browser
    event.preventDefault();
    if (this.form.checkBreak) return;
    if (!this.form.checkValidity()) {
      this.form.reportValidity();
      return;
    }

    if (this.#timeout) clearTimeout(this.#timeout);

    // Check if the add to cart button is disabled and do an early return if it is
    if (!addToCartButton || addToCartButton?.getAttribute('disabled') === 'true') return;
    addToCartButton.setAttribute("disabled", "true");
    addToCartButton.setAttribute("aria-busy", "true");
    const formData = new FormData(this.form);
    if (this.cart) formData.append('sections', this.cart.sectionId);
    const fetchCfg = fetchConfig('javascript', { body: formData });
    fetch(`${Shopify.routes.root}cart/add.js`, {
      ...fetchCfg,
      headers: {
        ...fetchCfg.headers,
        Accept: 'text/html',
      },
    })
      .then((response) => response.json())
      .then((response) => {
        addToCartButton.removeAttribute("disabled");
        addToCartButton.removeAttribute("aria-busy");
        if (response.status) {
          // Error from Shopify
          window.dispatchEvent(new CartErrorEvent(this.id, response.message));
          if (addToCartError) {
            addToCartError.removeAttribute('hidden');
            $4('.hdt-error-message', addToCartError).textContent = response.message;
          }
          // When we add more than the maximum amount of items to the cart, we need to dispatch a cart update event
          // because our back-end still adds the max allowed amount to the cart.
          document.dispatchEvent(new CustomEvent(cartReload));
          // this.dispatchEvent(
          //   new CartAddEvent(
          //     {},
          //     id.toString(),
          //     response,
          //     formData.get("action_added"),
          //     'product-form-component',
          //     {
          //       didError: true,
          //       itemCount: Number(formData.get('quantity')) || Number(this.dataset.quantityDefault),
          //       productId: this.dataset.productId
          //     }
          //   )
          // );
          return;
        } else {
          // Success from Shopify
          const id = this.isFrmBundle ? 'Bundle' : formData.get('id');
          if (addToCartError) {
            addToCartError.setAttribute('hidden', '');
          }

          if (!id) throw new Error('Form ID is required');

          // Add aria-live region to inform screen readers that the item was added
          addToCartButton.setAttribute('aria-live', 'polite');

            // this.#setLiveRegionText(addedText);

            // setTimeout(() => {
            //   this.#clearLiveRegionText();
            // }, 5000);
          //console.log('Success: add to cart', response);
          this.dispatchEvent(
            new CartAddEvent(
              {},
              id.toString(),
              response,
              formData.get("action_added"),
              'product-form-component',
              {
                itemCount: Number(formData.get('quantity')) || Number(this.dataset.quantityDefault),
                productId: this.dataset.productId,
                sections: response.sections,
              }
            )
          );
          if (themeHDN.settings.actionAfterATC == 'no') {
            document.dispatchEvent(new CustomEvent(cartReload));
          }
        }
      })
      .catch((error) => {
        console.error(error);
      })
      .finally(() => {
        // add more thing to do in here if needed.
      });
  }
  get cart() {
    return this._cart = this._cart || $4('[ref="hdt-cart"]');
  }
}

