class BackInStock extends VariantChangeBase {
  connectedCallback() {

    // Listen to form submit to store product handle and return_to search params if inside Quick View
    const notifyForm = this.querySelector('form');
    notifyForm?.addEventListener('submit', () => {
      const quickViewModal = this.closest('#hdt-quick-view-modal');
      if (quickViewModal) {
        const lazyModal = quickViewModal.parentElement;
        const handle = lazyModal?.btnOpening?.getAttribute('handle');
        if (handle) {
          const returnToInput = this.querySelector('[name="return_to"]');
          const returnToUrl = returnToInput ? returnToInput.value : '';
          let searchParams = '';
          if (returnToUrl) {
            try {
              searchParams = new URL(returnToUrl, location.origin).search;
            } catch (e) {
              console.error(e);
            }
          }
          sessionStorage.setItem('the4:quickview:reopen', JSON.stringify({
            handle: handle,
            search: searchParams
          }));
        }
      }
    });

    if ( this.hasAttribute('is-pr-default') ) return;
    this.select = $4('[back-instock-select]', this);
    this.return_to = $4('[back-instock-return-to]', this);
    this.originalText = $4('[back-instock-text]', this).textContent;
    this.elReplace = $4('[name="contact[product]"]', this);

    this.select?.addEventListener('change', (e) => {
      this.elReplace.textContent = this.originalText.replace('nt94_name', this.select.selectedOptions[0].textContent).replace('nt94_vid', this.select.value);
    });

    super.connectedCallback();
  }
  onVariantChanged(event) {
    const variant = event.detail.variant;
    if (location.href.includes('contact%5Bid%5D') || location.href.includes('contact[id]') || location.href.includes('contact_posted=true')) {
      const url = new URL(location.href);
      url.searchParams.delete('contact_posted');
      url.searchParams.delete('customer_posted');
      url.searchParams.delete('form_type');
      for (const key of [...url.searchParams.keys()]) {
        if (key.startsWith('contact[') || key.startsWith('contact%5B')) {
          url.searchParams.delete(key);
        }
      }
      url.hash = '';
      const newSearch = url.searchParams.toString();
      history.replaceState({}, '', url.pathname + (newSearch ? '?' + newSearch : '') + url.hash);
    }
    if (!variant) {
      this.hidden = true;
      this.removeAttribute('data-variant-available');
      return;
    }
    if (this.hasAttribute('toogle-hidden')) this.hidden = variant && variant.available;
    this.setAttribute('data-variant-available', variant.available);
    this.querySelectorAll('.hdt-form__message').forEach((el) => {
      el.remove();
    });
    if (variant && this.select && !variant.available && this.select.value != variant.id) {
      this.select.value = variant.id;
      this.select.dispatchEvent(new Event("change", { bubbles: false }));
    }
  }
};
