_form_atc_visible = new WeakSet();
form_atc_visible_fn = function(entries){

  if (this.variantPicker?.hasAttribute('no-pick')) {
    stickyRunOne = false;
    document.body.style.setProperty('--sticky-atc-height', '0px');
    return;
  }

  document.body.style.removeProperty('--sticky-atc-height');
  const formEntry = entries.find((entry) => entry.target === getterGet(_formElement, this));
  const quickOrderEntry = getterGet(_quickOrderElement, this) ? entries.find((entry) => entry.target === getterGet(_quickOrderElement, this)) : false;
  const footerEntry = getterGet(_footerElement, this) ? entries.find((entry) => entry.target === getterGet(_footerElement, this)) : false;  
  // console.log(formEntry)
  
  // Hide sticky when footer visible
  if (footerEntry && footerEntry.isIntersecting) {
    document.body.classList.remove("sticky-shown");
    return; // Exit early to prevent sticky from showing when footer is visible
  }
  
  if (formEntry) {
    getterAdd(_latestFormCondition, this, !formEntry.isIntersecting && formEntry.boundingClientRect.bottom < 0, true);
  }
  if (quickOrderEntry && getterGet(_quickOrderElement, this)) {
    getterAdd(_latestFormCondition, this, !quickOrderEntry.isIntersecting, true);
  }
  document.body.classList.toggle("sticky-shown", getterGet(_latestFormCondition, this));
  if (stickyRunOne && !getterGet(_latestFormCondition, this)) {
    setTimeout(() => {
      //getterAdd(_latestFormCondition, this, !formEntry.isIntersecting && (window.innerHeight + Math.round(window.scrollY)) >= document.body.offsetHeight, true);

      getterAdd(_latestFormCondition, this, (window.innerHeight + Math.round(window.scrollY)) >= document.body.offsetHeight, true);
      document.body.classList.toggle("sticky-shown", getterGet(_latestFormCondition, this));
      stickyRunOne = false
    }, 100);
  }
}

