// cart discount
class CartDiscount extends HTMLElement {
  #abortController;
  constructor() {
    super();
  }

  connectedCallback() {
    this.#abortController = new AbortController();
    
    // Add input handler to show/hide Apply button
    const input = this.querySelector('[data-cart-discount-input]');
    if (input) {
      input.addEventListener('input', this.handleInputChange.bind(this), { signal: this.#abortController.signal });
    }
    
    // Add click handler for Apply button
    const applyButton = this.querySelector('[data-cart-discount-apply]');
    if (applyButton) {
      applyButton.addEventListener('click', this.handleApplyClick.bind(this), { signal: this.#abortController.signal });
    }
    
    // Add click handler for remove discount buttons - use document with early return for performance
    document.addEventListener('click', this.handleRemoveDiscount.bind(this), { signal: this.#abortController.signal });
  }

  disconnectedCallback() {
    this.#abortController.abort();
  }

  handleInputChange(event) {
    const input = event.target;
    const applyButton = this.querySelector('[data-cart-mini-discount-apply]');
    if (applyButton) {
      applyButton.style.display = input.value ? 'inline-flex' : 'none';
    }
  }

  async handleApplyClick(event) {
    const input = this.querySelector('[data-cart-discount-input]');
    if (!input) return;

    var discount = input.value;
    if (input.hasAttribute('data-value')) {
      const inputValue = input.value.trim();
      const dataValue = input.getAttribute('data-value').trim();
      if (dataValue) {
        discount = `${inputValue},${dataValue}`;
        input.setAttribute('data-value', discount);
      }
    }
    const errorElement = this.querySelector('[data-cart-discount-error]');
    const sections = [this.closest('.shopify-section').id.replace('shopify-section-', '')];
    
    // Trigger loading start
    document.dispatchEvent(new CustomEvent('theme:loading:doing'));
    
    try {
      const response = await fetch(`${Shopify.routes.root}cart/update.js`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          discount: discount,
          sections: sections
        })
      });

      const data = await response.json();
      if (response.ok && data.discount_codes[0].applicable) {

        // Clear any previous error messages
        if (errorElement) {
          errorElement.textContent = '';
          errorElement.style.display = 'none';
        }

        // Refresh cart drawer if it exists
        document.dispatchEvent(new CustomEvent(cartReload));
      } else {
        // Handle error case
        if (errorElement) {
          // errorElement.textContent = data.description || 'Invalid discount code';
          errorElement.style.display = 'block';
        }
        input.value = ''; // Clear invalid input
        const applyButton = this.querySelector('[data-cart-mini-discount-apply]');
        if (applyButton) {
          applyButton.style.display = 'none';
        }
      }
    } catch (error) {
      console.error('Error applying discount:', error);
      if (errorElement) {
        errorElement.textContent = 'Error applying discount code';
        errorElement.style.display = 'block';
      }
    } finally {
      // Trigger loading end
      document.dispatchEvent(new CustomEvent('theme:loading:done'));
    }
  }

  async handleRemoveDiscount(event) {
    // Early return if click is not on remove button - optimize performance
    const removeButton = event.target.closest('.hdt-discount-remove');
    if (!removeButton) return;

    const discountCodeToRemove = removeButton.dataset.discountCode;
    if (!discountCodeToRemove) return;

    const sections = [this.closest('.shopify-section').id.replace('shopify-section-', '')];

    // Trigger loading start
    document.dispatchEvent(new CustomEvent('theme:loading:doing'));

    try {
      // Get current discount codes from data-value attribute
      const discountInput = this.querySelector('[data-cart-discount-input]');
      let currentDiscountCodes = [];
      
      if (discountInput && discountInput.hasAttribute('data-value')) {
        const dataValue = discountInput.getAttribute('data-value').trim();
        if (dataValue) {
          // Parse comma-separated discount codes
          currentDiscountCodes = dataValue.split(',').map(code => code.trim()).filter(code => code);
        }
      }

      // Remove the specific discount code
      const remainingDiscountCodes = currentDiscountCodes.filter(code => code !== discountCodeToRemove);

      // Update cart with remaining discount codes (or empty string if none left)
      const discountValue = remainingDiscountCodes.length > 0 
        ? remainingDiscountCodes.join(',') 
        : '';

      const response = await fetch(`${Shopify.routes.root}cart/update.js`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          discount: discountValue,
          sections: sections
        })
      });
      const data = await response.json();

      if (response.ok) {
        // Trigger cart refresh
        document.dispatchEvent(new CustomEvent(cartReload));
        // document.dispatchEvent(new DiscountUpdateEvent(data, this.id));

        // Update discount input and data-value attribute
        if (discountInput) {
          if (remainingDiscountCodes.length === 0) {
            discountInput.value = '';
            discountInput.removeAttribute('data-value');
          } else {
            discountInput.setAttribute('data-value', remainingDiscountCodes.join(','));
          }
        }
      }
    } catch (error) {
      console.error('Error removing discount:', error);
    } finally {
      // Trigger loading end
      document.dispatchEvent(new CustomEvent('theme:loading:done'));
    }
  }
}
