_allow_update_progress_bar = new WeakMap();
_update_progress_bar = new WeakSet();
update_progress_bar_fn = function() {
  const findRange = (value, ranges) => {
    const sortedRanges = [...ranges].sort((a, b) => a - b);
    return sortedRanges.find((range, i) => 
      value >= range && (i === sortedRanges.length - 1 || value < sortedRanges[i + 1])
    ) ?? sortedRanges[0];
  };

  const colors = JSON.parse(getterGet(_color_progress_bar, this) ?? '{}');
  const fixedNum = parseFloat((this.progress + '').slice(0, 3));
  
  const ranges = Object.keys(colors)
    .map(Number)
    .sort((a, b) => a - b);
  
  const rangeValue = findRange(fixedNum, ranges);
  Object.entries(colors)?.forEach(([key, item]) => {
    this.parentElement?.classList.toggle(item, parseFloat(key) === rangeValue);
  });
  this.style.setProperty('--progress-rate', `${this.progress}`);

  // this.parentElement?.addEventListener(ThemeEvents.progressBarChange, (event) => {
  //   console.log(event.detail.rangeValue);
  // });
  if( this.parentElement?.tagName == 'HDT-FREE-SHIPPING-BAR') {
    this.parentElement?.dispatchEvent(new CustomEvent(ThemeEvents.progressBarChange, { bubbles: true, detail: { rangeValue: this.progress } }));
  }
};
