_update_group_media = new WeakSet();
update_group_media_fn = function(variantOrEvent) {
  const options = variantOrEvent.options || variantOrEvent.detail.options;
  if (!this.updateGroupFilter) return;
  let isreInit = false;
  options.forEach((value, index) => {
    if ($$4(`[data-group-name="option${index}"][data-group-value="${value}"][hidden]`).length && this.sliderMain.isActive) {
      //console.log(this, $4('[data-media-type].is-selected hdt-video-player', this))
      $4('[data-media-type].is-selected hdt-video-player[loaded]', this)?.pause();
      isreInit = true;
    }
    //console.log(isreInit && this.sliderMain.isActive)
    $$4(`[data-group-name="option${index}"]`, this).forEach((media) => {
      if ( media.getAttribute('data-group-value') == value) {
        media.removeAttribute('hidden');
      } else {
        media.setAttribute('hidden', '');
      }
    });
  });
  if (isreInit) {
    this.sliderMain.reInit();
    this.sliderThumb?.reInit();
  }
};
_slider_main_select = new WeakSet();
slider_main_select_fn = function(event) {
  //console.log('slider_main_select_fn: ', event.detail)
  // if (this.disableSelectVariant) {
  //   this.disableSelectVariant = false;
  //   return;
  // }
  this.updateAttrPsw(event);
  const sliderApi = event.detail.sliderApi,
        selectedSlide = sliderApi.slideNodes()[sliderApi.selectedScrollSnap()],
        prevSlide = sliderApi.slideNodes()[sliderApi.previousScrollSnap()],
        mediaId   = selectedSlide.getAttribute('data-media-id') || null,
        variantsId = (selectedSlide.dataset.variantsId || '').split(';'),
        firstOption = (selectedSlide.dataset.firstOption || '').split(',');

  // variantsId.indexOf(this.form.id.value to detech media has need run fn selected
  if (mediaId && this.variantPicker && this.hasAttribute('update-when-variant-change') && variantsId[0] && variantsId.indexOf(this.form.id.value) < 0 ) {
    //console.log('mediaId', mediaId)
    this.variantPicker.selectVariantByID(variantsId[0], firstOption, false);
  }
  switch (prevSlide.getAttribute("data-media-type")) {
    case "video":
    case "external_video":
    //case "model":
      //$4('hdt-video-player[loaded], hdt-model-player[loaded]', prevSlide)?.pause();
      $4('hdt-video-player[loaded]', prevSlide)?.pause();
  }

  switch (selectedSlide.getAttribute("data-media-type")) {
    case "video":
    case "external_video":
      if (this.hasAttribute("autoplay-media")) $4('hdt-video-player', selectedSlide).play();
      break;
    case "model":
      if (!matchMediaQuery("mobile")) $4('hdt-model-player', selectedSlide).play();
      break;
  }
};
