class closeAnnounceWrap extends HTMLElement {
  constructor() {
    super();
    if (sessionStorage.getItem(announceSize) === "true") {
      announceSize = null;
      return;
    }
    this.addEventListener('click', (e) => {
      if (!Shopify.designMode) sessionStorage.setItem(announceSize, "true");
      let $section = this.closest('.hdt-section-group');
      $section.style.setProperty('overflow', 'hidden');
      animate($section, { height: [`${$section.clientHeight}px`, '0px'] }).finished.then(() => {
        $section.classList.add('hdt-announcement-hidden');
        announceSize = null; // announceSize can be garbage collected
      });
    });
  }
}
customElements.define("wrapp-close-announce", closeAnnounceWrap);

// --------------------------
// lazyHTML- https://web.dev/articles/fetch-priority
// --------------------------
class lazyHTML extends HTMLElement {
  #abortController;
  check = true;
  constructor() {
    super();
  }
  connectedCallback() {
    this.#abortController = new AbortController();
    const options = {
      priority: this.getAttribute('priority') || 'low',
      signal: this.#abortController.signal
    },
    url = this.url || this.getAttribute('url') || `${Shopify.routes.root}?section_id=${this.getAttribute('section-id')}`;
    if (url) this.lazyFetch(url, options);
  }
  disconnectedCallback() {
    if (this.check) this.#abortController.abort();
  }
  async lazyFetch(url, options) {
    const response = await fetchCache(url, '', options),
          tempDiv  = new DOMParser().parseFromString(await response.text(), "text/html");
    this.check = false;
    const formLocal = $4('.shopify-localization-form', tempDiv);
    if (formLocal) {
      const language = $id4('localization_form_language');
      $4('[name="return_to"]', formLocal).value = language && language.return_to ? language.return_to.value : location.pathname;
    }
    this._replace(tempDiv);
  }
  _replace(tempDiv) {
    this.replaceWith(...tempDiv.body.children);
    this.dispatchEvent(new CustomEvent("lazyhtml:added", { bubbles: true }));
  }
}
// --------------------------
// Lazy Submenu
// --------------------------
var cachMenuURl = new Map();
class lazySubmenu extends lazyHTML {
  check = true;
  url = `${Shopify.routes.root}search?type=product&q=submenu${this.getAttribute('key') || ''}&section_id=${this.dataset.section}`;
  constructor() {
    super();
  }
  async lazyFetch(url, options) {
    if (!cachMenuURl.has(url)) {
      cachMenuURl.set(url, true);
      const response = await fetchCache(url, '', options),
            tempDiv  = new DOMParser().parseFromString(await response.text(), "text/html");
      this.check = false;
      this._replace(tempDiv);
      $$4(`hdt-lazy-submenu[data-section="${this.dataset.section}"]:not([id="${this.id}"])`).forEach( (el) => {
        el.dispatchEvent(new CustomEvent(`loaded:lazy`, { bubbles: false, detail: { tempDiv } }));
      });
    } else {
      this.addEventListener('loaded:lazy', (event) => this._replace( event.detail.tempDiv) );
    }
  }
  _replace(tempDiv) {
    this.innerHTML = tempDiv.querySelector(`#${this.id}`).innerHTML;
    this.dispatchEvent(new CustomEvent("products:update", { bubbles: true }));
    this.dispatchEvent(new CustomEvent("lazyhtml:added", { bubbles: true }));
  }
}

customElements.define("hdt-lazy-html", lazyHTML);
customElements.define("hdt-lazy-submenu", lazySubmenu);

